def axis(k, v, h):
    n = len(k)
    a = np.zeros((n, n))
    for i in range(n):
        for step in (-1, 1):
            j = (i + step) % n
            c = (k[i] + k[j]) / (2 * h * h) + max(-step * v[i], 0) / h
            a[i, j] -= c
            a[i, i] += c
    return a
